import java.io.*;
import java.util.*;

class Main {

    public static class Scanner {
        private BufferedReader reader;
        private String[] buffer;
        private int index;

        public Scanner(BufferedReader reader) {
            this.reader = reader;
            this.buffer = new String[0];
            this.index = 0;
        }

        public <T> T token(Class<T> clazz) {
            while (true) {
                if (index < buffer.length) {
                    String token = buffer[index++];
                    if (clazz == Long.class) {
                        return clazz.cast(Long.parseLong(token));
                    } else if (clazz == Integer.class) {
                        return clazz.cast(Integer.parseInt(token));
                    } else if (clazz == String.class) {
                        return clazz.cast(token);
                    } else {
                        throw new RuntimeException("Unsupported type");
                    }
                }
                try {
                    String input = reader.readLine();
                    if (input == null) {
                        throw new RuntimeException("Failed read");
                    }
                    buffer = input.trim().split("\\s+");
                    index = 0;
                } catch (IOException e) {
                    throw new RuntimeException("Failed read", e);
                }
            }
        }
    }

    static long zeros_factorial(long n) {
        long ans = 0;
        while (n > 0) {
            ans += n / 5;
            n /= 5;
        }
        return ans;
    }

    static long search(long m) {
        long lo = 0;
        long hi = 500000;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (zeros_factorial(mid) >= m) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return lo;
    }

    static void solve(Scanner scan, BufferedWriter out) throws IOException {
        long m = scan.token(Long.class);
        long n = search(m);
        if (zeros_factorial(n) == m) {
            out.write("5\n");
            for (int i = 0; i < 5; i++) {
                out.write((n + i) + " ");
            }
            out.write("\n");
        } else {
            out.write("0\n");
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader stdin = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter stdout = new BufferedWriter(new OutputStreamWriter(System.out));
        Scanner scan = new Scanner(stdin);
        solve(scan, stdout);
        stdout.flush();
    }
}

